CREATE TABLE audit_log (
    id INT AUTO_INCREMENT PRIMARY KEY,
    note VARCHAR(100) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELIMITER //

CREATE FUNCTION write_audit(note VARCHAR(100)) RETURNS INT
MODIFIES SQL DATA
BEGIN
    INSERT INTO audit_log (note) VALUES (note);
    RETURN LAST_INSERT_ID();
END //

DELIMITER ;

CREATE FUNCTION audited(note VARCHAR(100)) RETURNS INT
DETERMINISTIC
RETURN write_audit(note);

CREATE FUNCTION tidied(note VARCHAR(100)) RETURNS VARCHAR(100)
DETERMINISTIC
RETURN LOWER(TRIM(note));
